stage.example:
const size = screen.stage();
if (size) {
  panel.set({ x: (size.width - 400) / 2 });
}

stage.exampleCs:
var size = screen.Stage();
if (size)
{
    panel.Set(new { x = (size["width"].AsNumber() - 400) / 2 });
}

on.example:
screen.focus();
screen.on('input', (action, phase) => {
  if (action === 'kcds_ui_back' && phase === 'press') {
    screen.close();
  }
});

on.exampleCs:
screen.Focus();
screen.On("input", (JsValue action, JsValue phase) =>
{
    if (action.AsString() == "kcds_ui_back" && phase.AsString() == "press")
    {
        screen.Close();
    }
});
